INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'roller skating', 'phrase', '/ˈrəʊlə ˌskeɪtɪŋ/', '滑旱冰', 'At the age of 68, he was brave enough to try roller skating.', '在68岁时,他还有勇气尝试滑旱冰。', 'Faster Higher Stronger', 44, 0, 'senior', 'wordlist', 'elective1', 'U3', 'roller skating', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'burst onto', 'phrase', '/ˌbɜːst ˈɒntə/', '突然出现在(指突然成功)', 'In the 1980s, the team burst onto the world stage.', '在20世纪80年代,这支队伍突然登上了世界舞台。', 'Faster Higher Stronger', 45, 0, 'senior', 'wordlist', 'elective1', 'U3', 'burst onto the scene', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u3.01', '①动名词作主语(Doing… + 谓语)', 'A2', 11, '外研社版选择性必修第一册 U3 — 句子主语位置要表示''做某事'',只能用动词的 -ing 形式(动名词);原形/单三/过去式等限定形式都不能直接作主语。', 1, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u3.02', '②形式主语 it（It is no use/no good/worth + doing）', 'A2', 11, '外研社版选择性必修第一册 U3 — It is no use / no good / worth / a waste of time 等结构后接动名词(doing),it 是形式主语;不能用不定式 to do 或限定动词形式。', 2, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe1u3.03', '③动名词主语作形式辨析与主谓一致（视为单数）', 'A2', 11, '外研社版选择性必修第一册 U3 — 动名词(短语)作主语时谓语用单数;并且作主语只能用 -ing 形式,干扰项为限定动词或复数谓语,使答案唯一。', 3, 'elective1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.01'), '"____ basketball on a muddy court taught Stephen to be creative."', 'Playing', 'Play', 'Plays', 'Played', 'A', '主语位置表示''打篮球这件事'',只能用动名词 Playing。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.01'), '"____ with great accuracy was another thing he had to learn."', 'Shoot', 'Shooting', 'Shoots', 'Shot', 'B', '主语表示''精准投篮'',用动名词 Shooting。', 2, 2, 'mcq');
