INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"Getting up early to train ____ a lot of willpower."', 'take', 'takes', 'are taking', 'have taken', 'B', '动名词主语视为单数 → takes。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"Working closely with your teammates ____ to better results."', 'lead', 'are leading', 'leads', 'have led', 'C', '动名词主语视为单数 → leads。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"Cheering for your team ____ the players feel stronger."', 'make', 'are making', 'have made', 'makes', 'D', '动名词主语视为单数 → makes。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"Practising the same move daily ____ boring, but it really works."', 'seems', 'seem', 'are', 'have', 'A', '动名词主语视为单数 → seems。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"Believing in yourself ____ the first step towards success."', 'are', 'is', 'were', 'have been', 'B', '动名词主语视为单数 → is。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ a healthy diet keeps young athletes in good shape."', 'Keep', 'Keeps', 'Keeping', 'Kept', 'C', '作主语只能用动名词 → Keeping。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ off the podium means the hard work starts all over again."', 'Step', 'Steps', 'Stepped', 'Stepping', 'D', '作主语只能用动名词 → Stepping。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ to the coach carefully saves you many mistakes."', 'Listening', 'Listen', 'Listens', 'Listened', 'A', '作主语只能用动名词 → Listening。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ for your country is a dream for many young players."', 'Play', 'Playing', 'Plays', 'Played', 'B', '作主语只能用动名词 → Playing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ the rules quickly helps a new player fit into the team."', 'Learn', 'Learns', 'Learning', 'Learned', 'C', '作主语只能用动名词 → Learning。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ after a serious injury is never easy for any athlete."', 'Return', 'Returns', 'Returned', 'Returning', 'D', '作主语只能用动名词 → Returning。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ the ball over the net at the right time won the match point."', 'Sending', 'Send', 'Sends', 'Sent', 'A', '作主语只能用动名词 → Sending。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ calm under pressure separates the best from the rest."', 'Stay', 'Staying', 'Stays', 'Stayed', 'B', '作主语只能用动名词 → Staying。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ every single day is how he keeps improving."', 'Practise', 'Practises', 'Practising', 'Practised', 'C', '作主语只能用动名词 → Practising。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective1' AND unit='U3' AND code='fe1u3.03'), '"____ as one team matters more than any single star player."', 'Fight', 'Fights', 'Fought', 'Fighting', 'D', '作主语只能用动名词 → Fighting。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Muddy Court', 'Near a small town in Virginia, a narrow dirt road led from Stephen Curry''s grandfather''s house to the woods. Far from the bright lights and shiny courts of the NBA, his grandfather had built a simple basket by fixing a piece of plastic to a pole. Like his father, Stephen spent many childhood hours playing on this muddy court. He probably did not realise it then, but it was where he learned to be creative. With every shot, the weak plastic backboard gave way a little. The bumps and rocks under the basket made the ball bounce in all directions, so knowing where it would go was never easy. He had to keep adjusting his own style. Shooting with great accuracy was another thing he had to learn, because only a perfect shot went into the heavy basket. In this way, practising day in and day out slowly helped Stephen sharpen his skills.', '记叙·库里的成长', 153, '[{"q":"Why was the muddy court important to Stephen?","answer":"A","options":["It taught him to play in a creative, flexible way.","It was a bright and modern NBA court.","It was where he first met his coach.","It was close to a famous stadium."],"explanation":"原文说他在那里学会了 creative 的转述;其余与文意不符。"},{"q":"What made the ball hard to control on that court?","answer":"B","options":["The rain that fell during games.","The rough, rocky ground beneath the hoop.","The size of the heavy basket.","The bright lights above the court."],"explanation":"原文 ''bumps and rocks… made the ball bounce in all directions'' 的转述。"},{"q":"How did Stephen finally improve his skills?","answer":"A","options":["By practising again and again over time.","By buying better equipment.","By moving to a city court.","By copying his grandfather exactly."],"explanation":"末句 ''practising day in and day out… sharpen his skills'' 的转述。"}]'::jsonb, '[{"word":"backboard","cn":"篮板"},{"word":"bounce","cn":"弹跳"},{"word":"sharpen","cn":"使提高"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Runner with One Shoe', 'Etenesh Diro had almost completed two thirds of the 3000-metre steeplechase when disaster struck. She got tangled up with some other runners, and the crash made her fall. Her right shoe started to come off. She tried to pull it back on, but doing so cost her precious time, and one after another the runners passed her. In the end she made a brave choice: she threw the shoe away. This meant she could get up quickly and fight for her place in the race. With just one shoe on and her right foot bare, she ran the rest of the way. Watching her refuse to quit raised a huge cheer from the crowd. Luckily, the judges later gave her a chance to compete in the final. She had lost a shoe, but that did not keep her from taking part. To many people, her race showed the true spirit of sport.', '记叙·迪罗的体育精神', 152, '[{"q":"What went wrong during Diro''s race?","answer":"B","options":["She started far too early.","She fell after getting tangled with other runners.","She forgot which way to run.","She felt ill before the start."],"explanation":"原文 ''got tangled up… made her fall'' 的转述。"},{"q":"Why did she throw her shoe away?","answer":"C","options":["Because the shoe was too old.","To give it to another runner.","So she could get up and keep racing quickly.","Because the judges told her to."],"explanation":"原文 ''she could get up quickly and fight for her place'' 的转述。"},{"q":"What does the writer think her race showed?","answer":"D","options":["That shoes do not matter in sport.","That the judges were unfair to her.","That she should have given up.","The real meaning of sporting spirit."],"explanation":"末句 ''the true spirit of sport'' 的转述。"}]'::jsonb, '[{"word":"bare","cn":"赤裸的"},{"word":"cheer","cn":"欢呼"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Gold in Rio', 'The Chinese women''s volleyball team holds a special place in the nation''s heart. In Rio, however, their road to gold was far from easy. The team was assigned to a very tough group, where it faced several strong opponents. Even after reaching the quarter-final as only the fourth team in the group, with just two wins in the preliminary matches, they refused to give up. Every member gave her all, including a spiker who had returned only months after heart surgery. Their perseverance paid off with an epic comeback against the defending champion in the quarter-final. Next they defeated the Netherlands in the semi-final, a team that had beaten them earlier. At last, showing steely nerves, they played a close match to seize the gold. Yet fighting spirit alone was not enough. As the Most Valuable Player said afterwards, teamwork was the real key, because strong cooperation matters more than the skill of any single player.', '记叙·中国女排夺金', 156, '[{"q":"What was the team''s situation after the group stage?","answer":"A","options":["They reached the quarter-final only as the fourth team.","They had won every single match easily.","They were sent home early.","They had no injured players at all."],"explanation":"原文 ''reaching the quarter-final as only the fourth team'' 的转述。"},{"q":"What is special about the spiker mentioned in the text?","answer":"B","options":["She had never played before.","She had recently come back from heart surgery.","She was the team''s coach.","She refused to join the final."],"explanation":"原文 ''returned only months after heart surgery'' 的转述。"},{"q":"According to the MVP, what mattered most to their success?","answer":"C","options":["The skill of one star player.","Good luck in every match.","The strength of their teamwork.","The weather in Rio."],"explanation":"原文 ''teamwork was the real key… cooperation matters more'' 的转述。"}]'::jsonb, '[{"word":"assign","cn":"分配"},{"word":"comeback","cn":"反扑"},{"word":"seize","cn":"夺取"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Honouring Sports Heroes', 'A sports role model is a sportsperson who inspires other people in some special way. In this spirit, a well-known award holds a ceremony every year to honour remarkable sportspeople from around the world. The very first ceremony took place in 2000 in a small European country, where a famous footballer received a lifetime award for everything he had achieved. Three years later, a Chinese basketball player became the first sportsperson from China to win the award. Then, in his home country in 2015, that same player and a famous tennis star both received awards on the same evening. Each year, the award gives a prize not only to single athletes but also to whole teams and to people who have come back from injury. These role models remind everyone what sporting spirit really means. Through their hard work and self-belief, they show that the words faster, higher and stronger are about far more than just winning medals.', '说明·劳伦斯体育奖', 158, '[{"q":"What is the purpose of the yearly ceremony?","answer":"D","options":["To sell tickets for football games.","To train young coaches.","To choose a new national sport.","To honour outstanding sportspeople each year."],"explanation":"原文 ''honour remarkable sportspeople… every year'' 的转述。"},{"q":"What did the Chinese basketball player do in 2003?","answer":"A","options":["He became the first Chinese person to win the award.","He retired from the sport.","He started the ceremony himself.","He moved to Europe."],"explanation":"原文 ''first sportsperson from China to win the award'' 的转述。"},{"q":"What do these role models help people understand?","answer":"B","options":["That medals are the only goal.","The true meaning of sporting spirit.","That sport is only for the young.","That teams never matter."],"explanation":"原文 ''remind everyone what sporting spirit really means'' 的转述。"}]'::jsonb, '[{"word":"ceremony","cn":"典礼"},{"word":"remarkable","cn":"非凡的"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Why Sport Matters', 'Many young people dream of winning a gold medal, but the real value of sport goes far beyond the result. Taking part in sport teaches lessons that last a lifetime. Training hard every day builds not only strong muscles but also a strong will. Losing a close game teaches you to stay calm and try again, and winning one teaches you to be humble. In team sports, working closely with others shows you that cooperation often matters more than personal skill. Doing sport is also good for the mind. After a long day of study, running, swimming or playing ball can clear your head and lift your mood. Best of all, the habits you form through sport stay with you. The athlete who learns to get up early, to keep going and to believe in herself carries these qualities into the rest of her life. That, many people believe, is the true prize that sport offers.', '议论·体育的价值', 156, '[{"q":"What is the main point of the passage?","answer":"C","options":["Only gold medals make sport worthwhile.","Team sports are always better than individual ones.","The benefits of sport go well beyond winning medals.","Sport is mainly about getting strong muscles."],"explanation":"全文中心 ''the real value of sport goes far beyond the result'' 的转述。"},{"q":"According to the text, what does losing a close game teach you?","answer":"D","options":["To stop playing for good.","To blame your teammates.","To win at any cost.","To keep your head and have another go."],"explanation":"原文 ''teaches you to stay calm and try again'' 的转述。"},{"q":"Why does the writer say sport is good for the mind?","answer":"A","options":["Because it refreshes the mind and improves how you feel.","Because it makes you richer.","Because it ends all study.","Because it removes the need for sleep."],"explanation":"原文 ''clear your head and lift your mood'' 的转述。"}]'::jsonb, '[{"word":"humble","cn":"谦逊的"},{"word":"cooperation","cn":"合作"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Sporting Moment', 'Last Saturday I went to our school playground to watch the final of the relay race at our annual tournament. It was an experience I will never forget. Before the race, everyone was quiet and still, and I had never imagined that the atmosphere at a sports event could feel so intense. Then the runners set off, and at once everyone went wild. We all stood up and started cheering and shouting, and it was like being hit by a huge wave of excitement. I could see the runners straining to go as fast as they could, while trying hard not to drop their batons at each change. The whole race was over in about a minute. It was Li Chong, the fastest student in our school, who first crossed the finish line. Everyone was on their feet. I was caught up in the excitement too and cheered so hard that I thought my lungs would burst. Being part of that moment felt truly wonderful.', '记叙·校运会接力', 165, '[{"q":"How did the atmosphere feel before the race?","answer":"B","options":["Noisy and relaxed the whole time.","Quiet at first, then suddenly very intense.","Boring from start to finish.","Cold and unfriendly."],"explanation":"原文 ''everyone was quiet and still… so intense'' 的转述。"},{"q":"What were the runners trying hard not to do?","answer":"C","options":["Cross the finish line.","Look at the crowd.","Drop their batons when changing.","Cheer for each other."],"explanation":"原文 ''trying hard not to drop their batons at each change'' 的转述。"},{"q":"How did the writer feel about being there?","answer":"D","options":["It was a waste of a Saturday.","It was frightening and unpleasant.","It was too long and tiring.","It was a wonderful moment to be part of."],"explanation":"末句 ''Being part of that moment felt truly wonderful'' 的转述。"}]'::jsonb, '[{"word":"intense","cn":"紧张的"},{"word":"baton","cn":"接力棒"}]'::jsonb, 2, 'elective1', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Technology in Sport', 'I love the way technology is changing modern sport. Using the latest (1)____, such as smart earphones, helps people get the best out of their training. Coaches can now (2)____ exactly how fast and how far an athlete runs. Video technology is also used to (3)____ our competitions, making sure that no one can (4)____. When two players reach the line at the same (5)____, a slow-motion replay shows the judges who really won. Best of all, instant replay lets fans (6)____ all the action again and again. In the past, (7)____ a great moment often meant it was gone forever. Today, however, we can save it and (8)____ it with friends online. Of course, machines cannot (9)____ hard work; an athlete still has to train every day. But used in the right way, technology can make sport fairer, safer and far more (10)____ for everyone.', 146, 2, '[{"q":"1","answer":"A","options":["equipment","weather","homework","music"],"explanation":"the latest equipment 最新器材。"},{"q":"2","answer":"B","options":["forget","measure","lose","sell"],"explanation":"measure how fast 测量速度。"},{"q":"3","answer":"C","options":["break","hide","judge","leave"],"explanation":"judge competitions 评判比赛。"},{"q":"4","answer":"D","options":["win","play","run","cheat"],"explanation":"make sure no one can cheat 没人作弊。"},{"q":"5","answer":"A","options":["moment","price","noise","colour"],"explanation":"at the same moment 同一时刻。"},{"q":"6","answer":"B","options":["eat","see","buy","throw"],"explanation":"let fans see the action 看回放。"},{"q":"7","answer":"C","options":["selling","eating","missing","buying"],"explanation":"missing a great moment 错过精彩瞬间。"},{"q":"8","answer":"D","options":["hide","lose","drop","share"],"explanation":"share it with friends 分享。"},{"q":"9","answer":"A","options":["replace","enjoy","watch","open"],"explanation":"cannot replace hard work 取代不了努力。"},{"q":"10","answer":"B","options":["boring","exciting","empty","quiet"],"explanation":"more exciting 更精彩。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Learning to Swim Fast', 'When I joined the school swimming team, I was the (1)____ member of all. The other swimmers were faster, and at first I felt I did not (2)____. My coach noticed this and gave me some simple (3)____. He told me that getting better takes time and that I should never (4)____ comparing myself with others. Every morning I got up early to (5)____ before class. Slowly, my times began to (6)____, and the strokes that once felt so hard became (7)____. The most important lesson I learned was that (8)____ up early and training day after day really pays (9)____. I may never win a gold medal, but swimming has made me stronger and far more (10)____ in myself.', 120, 2, '[{"q":"1","answer":"C","options":["tallest","richest","slowest","oldest"],"explanation":"the slowest member 最慢的。"},{"q":"2","answer":"D","options":["sleep","cook","drive","belong"],"explanation":"did not belong 觉得不属于。"},{"q":"3","answer":"A","options":["advice","money","food","tickets"],"explanation":"some simple advice 一些建议。"},{"q":"4","answer":"B","options":["start","stop","enjoy","begin"],"explanation":"never stop comparing... 这里意为别老拿自己跟别人比 → stop。"},{"q":"5","answer":"C","options":["sleep","shop","practise","rest"],"explanation":"got up early to practise 练习。"},{"q":"6","answer":"D","options":["rise","fall","stay","improve"],"explanation":"times began to improve 成绩进步。"},{"q":"7","answer":"A","options":["easier","harder","worse","longer"],"explanation":"became easier 变得更容易。"},{"q":"8","answer":"B","options":["giving","getting","selling","losing"],"explanation":"getting up early 早起。"},{"q":"9","answer":"C","options":["in","down","off","out"],"explanation":"pays off 有回报。"},{"q":"10","answer":"D","options":["afraid","bored","sorry","confident"],"explanation":"more confident 更自信。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'The Senior Sports Club', 'Yesterday I started helping at a sports club for older people, and it has made me (1)____ later life with fresh eyes. Some members like to do (2)____ because it helps them keep their muscles strong. Others love ball games: many enjoy (3)____ table tennis, while a few play badminton or (4)____ golf. One man, who is sixty-eight, was even brave enough to try roller (5)____. Not only did he have courage, he was much (6)____ than me! What surprised me most was how (7)____ everyone was. Nobody worried about (8)____; they just wanted to stay healthy and have fun together. Watching them reminded me that sport is not only for the (9)____. It is never too late to start, and a little exercise every day can (10)____ us all a lot of good.', 134, 2, '[{"q":"1","answer":"A","options":["see","sell","lose","eat"],"explanation":"see later life 看待晚年。"},{"q":"2","answer":"B","options":["maths","yoga","shopping","cooking"],"explanation":"do yoga 练瑜伽。"},{"q":"3","answer":"C","options":["selling","eating","playing","buying"],"explanation":"playing table tennis 打乒乓球。"},{"q":"4","answer":"D","options":["sleep","cook","drive","play"],"explanation":"play golf 打高尔夫。"},{"q":"5","answer":"A","options":["skating","reading","cooking","singing"],"explanation":"roller skating 滑旱冰。"},{"q":"6","answer":"B","options":["slower","faster","shorter","older"],"explanation":"much faster than me 比我快。"},{"q":"7","answer":"C","options":["angry","afraid","active","tired"],"explanation":"how active 多有活力。"},{"q":"8","answer":"D","options":["cooking","sleeping","shopping","winning"],"explanation":"worried about winning 不在乎输赢。"},{"q":"9","answer":"A","options":["young","rich","tall","busy"],"explanation":"not only for the young 不只属于年轻人。"},{"q":"10","answer":"B","options":["sell","do","lose","break"],"explanation":"do us good 对我们有益。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'More Than One Player', 'Many people think basketball is all about the one (1)____ who scores the most points. In fact, no player can win a game (2)____. A team is like a machine: if every part does its (3)____ and works well with the others, the whole team moves (4)____. The best teams share the ball, talk to each other and (5)____ their teammates when a shot is missed. When players trust one another, (6)____ closely together leads to far better results. A selfish star may score a lot, but a team with strong (7)____ will usually win in the end. That is (8)____ good coaches spend so much time teaching players to pass, to listen and to support. After all, the word on every winner''s lips is rarely ''I''. (9)____ as one team matters far more than any single (10)____ moment.', 139, 2, '[{"q":"1","answer":"C","options":["teacher","driver","player","singer"],"explanation":"the one player 那名球员。"},{"q":"2","answer":"D","options":["together","early","twice","alone"],"explanation":"win a game alone 独自取胜。"},{"q":"3","answer":"A","options":["job","price","noise","colour"],"explanation":"does its job 各司其职。"},{"q":"4","answer":"B","options":["badly","smoothly","slowly","sadly"],"explanation":"moves smoothly 运转顺畅。"},{"q":"5","answer":"C","options":["blame","leave","support","sell"],"explanation":"support their teammates 支持队友。"},{"q":"6","answer":"D","options":["sleeping","shopping","eating","working"],"explanation":"working closely together 紧密协作。"},{"q":"7","answer":"A","options":["teamwork","weather","noise","money"],"explanation":"strong teamwork 强大的团队配合。"},{"q":"8","answer":"B","options":["when","why","where","what"],"explanation":"That is why 这就是为什么。"},{"q":"9","answer":"C","options":["Selling","Sleeping","Fighting","Shopping"],"explanation":"Fighting as one team 作为一个整体拼搏(动名词作主语)。"},{"q":"10","answer":"D","options":["boring","empty","quiet","shining"],"explanation":"any single shining moment 任何闪光时刻。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'The Long Race', 'Lin had always wanted to (1)____ in a full marathon. Everyone told her that forty-two kilometres was too (2)____ for a beginner, but she refused to (3)____ up. For half a year she trained almost every day, often running before the sun (4)____. On the day of the race, the first twenty kilometres felt (5)____, and she smiled as she passed the cheering crowds. Then her legs began to (6)____, and each step became a struggle. A voice in her head told her to stop, but she kept (7)____ herself, ''Just one more kilometre.'' Slowly, painfully, she moved (8)____. When she finally crossed the finish line, she was the (9)____ runner of all, yet the cheer for her was the loudest. Her long months of hard work had truly (10)____ off.', 131, 2, '[{"q":"1","answer":"A","options":["run","sleep","cook","shop"],"explanation":"run in a marathon 跑马拉松。"},{"q":"2","answer":"B","options":["short","far","easy","cheap"],"explanation":"too far 太远。"},{"q":"3","answer":"C","options":["wake","stand","give","look"],"explanation":"give up 放弃。"},{"q":"4","answer":"D","options":["fell","sold","broke","rose"],"explanation":"before the sun rose 日出之前。"},{"q":"5","answer":"A","options":["easy","wrong","empty","late"],"explanation":"felt easy 感觉轻松。"},{"q":"6","answer":"B","options":["dance","ache","sing","grow"],"explanation":"legs began to ache 腿开始酸痛。"},{"q":"7","answer":"C","options":["selling","hiding","telling","losing"],"explanation":"kept telling herself 不断告诉自己。"},{"q":"8","answer":"D","options":["away","back","down","forward"],"explanation":"moved forward 向前。"},{"q":"9","answer":"A","options":["slowest","tallest","richest","youngest"],"explanation":"the slowest runner 最慢的跑者。"},{"q":"10","answer":"B","options":["taken","paid","sold","broken"],"explanation":"had paid off 得到了回报。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U3', 'Not Only to Win', 'More than a hundred years ago, the founder of the modern Olympic Games said that the most important thing was not to win but to take (1)____. Many people still argue about these (2)____ today. Some believe that trying your (3)____ matters more than the result, while others feel that winning is (4)____ that counts. The truth, perhaps, lies in the (5)____. Of course every athlete wants to (6)____ the gold, and there is nothing wrong with that. But sport also teaches us to play (7)____, to respect our opponents and to keep going when things get (8)____. An athlete who loses with a smile and shakes hands with the (9)____ shows a kind of strength that no medal can measure. In the end, the way you play may matter just as (10)____ as whether you win.', 137, 2, '[{"q":"1","answer":"C","options":["money","rest","part","place"],"explanation":"take part 参与。"},{"q":"2","answer":"D","options":["prices","songs","machines","words"],"explanation":"argue about these words 这些话。"},{"q":"3","answer":"A","options":["best","price","noise","weather"],"explanation":"trying your best 尽力。"},{"q":"4","answer":"B","options":["nothing","all","anyone","nobody"],"explanation":"winning is all that counts 唯一重要的。"},{"q":"5","answer":"C","options":["corner","garden","middle","market"],"explanation":"lies in the middle 在两者之间。"},{"q":"6","answer":"D","options":["lose","drop","miss","win"],"explanation":"win the gold 赢得金牌。"},{"q":"7","answer":"A","options":["fairly","badly","slowly","loudly"],"explanation":"play fairly 公平竞赛。"},{"q":"8","answer":"B","options":["easy","hard","funny","cheap"],"explanation":"when things get hard 困难时。"},{"q":"9","answer":"C","options":["shop","city","winner","price"],"explanation":"shakes hands with the winner 与胜者握手。"},{"q":"10","answer":"D","options":["little","few","less","much"],"explanation":"just as much as 一样重要。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 Which Sport to Try', '外研社版选择性必修第一册 U3 · dialogue', 3, 'Mia: The school sports club is open to everyone this term. Which sport will you try, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·短文 Faster, Higher, Stronger', '外研社版选择性必修第一册 U3 · passage', 2, 'The motto of the Olympic Games is ''Faster, Higher, Stronger''.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 Going to the Match', '外研社版选择性必修第一册 U3 · dialogue', 3, 'Ben: There''s a big basketball match this Saturday. Do you want to come?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·短文 A Basketball Star', '外研社版选择性必修第一册 U3 · passage', 2, 'As a boy, one famous player learned the game on a poor backyard court.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·对话 After Losing the Game', '外研社版选择性必修第一册 U3 · dialogue', 3, 'Leo: We lost the final by just two points. I feel terrible.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U3 听力·短文 Why We Do Sport', '外研社版选择性必修第一册 U3 · passage', 2, 'Doing sport is good for both the body and the mind.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write about a Sporting Moment(写一个体育时刻)', 'An Unforgettable Sporting Moment', '请用英语写一篇约80词的短文,描述一个让你难忘的体育时刻(如一场比赛、一次接力或一次夺冠)。内容包括:① 简要介绍是什么比赛、何时何地;② 你看到和听到了什么;③ 你当时的感受。注意:用一两个动名词作主语的句子(如 Watching… was…)让行文更地道。', 'Write a short passage (about 80 words) about an unforgettable sporting moment you saw or took part in. Include: 1) what the event was, and when and where it happened; 2) what you saw and heard; 3) how you felt. Try to use one or two sentences with an -ing form as the subject (e.g. Watching… was…).', '["总起:是什么比赛、何时何地(Last … , I went to … to watch …)","所见所闻(I could see … / Everyone started cheering …)","内心感受(It was so exciting that …)","用动名词作主语让句子地道(Watching … was … / Being part of … felt …)"]'::jsonb, 70, 100, 'Last Saturday, I watched the relay final at our school sports tournament. Before the race, everyone went quiet, and the atmosphere was very intense. Then the runners set off, and watching them race down the track was thrilling. Everyone stood up, cheering and shouting. I could see the runners straining to go faster, trying hard not to drop their batons. The whole race was over in a minute, and our class won! Being part of that moment felt truly wonderful, and I will never forget it.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Watching them race down the track was thrilling.","Before the race, everyone went quiet, and the atmosphere was very intense.","I could see the runners straining to go faster.","Being part of that moment felt truly wonderful."]'::jsonb, '[{"wrong":"Watch them race was thrilling.","correct":"Watching them race was thrilling.","note":"主语位置表示''看…这件事'',要用动名词 Watching。"},{"wrong":"Being part of that moment feel wonderful.","correct":"Being part of that moment felt wonderful.","note":"动名词短语作主语视为单数,谓语用单数(过去式 felt)。"},{"wrong":"It was no use to give up.","correct":"It was no use giving up.","note":"It is no use 后接动名词,不用不定式。"}]'::jsonb, '【体育时刻结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U3', '{"title":"动名词作主语 · 形式主语 it 速查","intro":"句子主语要表示''做某事''时,用动词的 -ing 形式(动名词);主语太长时常用 it 作形式主语放在句首。口诀:主语位置要''做某事''→ 用 doing;no use / worth 后→ 用 doing;动名词主语→ 谓语用单数。","table":{"headers":["结构","用法 / 例句"],"rows":[["Doing… + 单数谓语","动名词作主语:Knowing where the ball would go wasn''t easy."],["It is no use / no good + doing","It is no use complaining about the result."],["It is worth / a waste of time + doing","It is worth practising every day."],["It is + adj + to do","形式主语 it 指代不定式:It is not easy to win gold."]]},"specialRules":[{"rule":"作主语只能用 -ing,原形/单三/过去式都不行","mark":"Playing basketball is fun.(不是 Play / Plays)"},{"rule":"动名词(短语)作主语 → 谓语用单数","mark":"Watching matches is his hobby.(is 不是 are)"},{"rule":"It is no use / no good / worth / a waste of time 后接 doing","mark":"It is no use giving up.(不是 to give up)"},{"rule":"it 也可作形式主语指代后面的不定式(to do)","mark":"It is hard to stay calm.(真主语是 to stay calm)"}],"why":["动名词兼有名词性质,能像名词一样放在主语位置;它表示一件''事'',所以谓语按单数处理。主语很长时,英语习惯把它后移,用 it 占住句首的形式主语位置,让句子头轻尾重、更好读。"],"gaokaoPoints":["动名词 vs 原形/不定式作主语的辨析;动名词主语的主谓一致(用单数)——语法填空、改错高频。","It is no use / no good / worth + doing 固定结构;与 It is + adj + to do 的形式主语对比。"],"examVsReal":[{"exam":"Getting up early is good for you.(书面/考试)","real":"It''s good to get up early. / Getting up early? Good for you!","note":"考试爱考动名词主语;口语里常用 it 形式主语或更随意的说法"},{"exam":"It is no use complaining.(考试)","real":"No point complaining. / What''s the use of complaining?","note":"考试用固定句型;口语有更短的变体,但意思相同"}]}'::jsonb, 'fltrp');
